using ErrorOr;
using FastEndpoints;
using Microsoft.AspNetCore.Http.HttpResults;
using Wolverine;

namespace Teck.Cloud.Stack;

/// <summary>Exercises the HTTP result boundary.</summary>
/// <param name="bus">The application dispatcher.</param>
public sealed class GetProductEndpoint(IMessageBus bus)
    : Endpoint<GetProductRequest, Results<Ok<ProductResponse>, ProblemHttpResult>>
{
    /// <inheritdoc />
    public override void Configure()
    {
        Get("/products/{Id}");
        Policies("Products.Read");
    }

    /// <inheritdoc />
    public override async Task<Results<Ok<ProductResponse>, ProblemHttpResult>> ExecuteAsync(
        GetProductRequest req,
        CancellationToken ct)
    {
        var result = await bus.InvokeAsync<ErrorOr<ProductResponse>>(req, ct).ConfigureAwait(false);
        return result.IsError
            ? TypedResults.Problem(statusCode: StatusCodes.Status404NotFound, title: "Not found")
            : TypedResults.Ok(result.Value);
    }
}

